import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    previous_limit = csv.field_size_limit()
    try:
        csv.field_size_limit(max(previous_limit, len(raw_csv)))
        records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"'))
    finally:
        csv.field_size_limit(previous_limit)

    def populated(row):
        return sum(bool(value.strip()) for value in row)

    header_index = next(
        (i for i, row in enumerate(records) if populated(row) >= 3),
        None,
    )
    if header_index is None:
        header_index = next(
            (i for i, row in enumerate(records) if populated(row)),
            None,
        )
    if header_index is None:
        return {"columns": [], "rows": []}

    header = records[header_index]
    rows = [row for row in records[header_index + 1:] if populated(row)]
    width = max([len(header)] + [len(row) for row in rows])
    header = header + [""] * (width - len(header))

    columns = []
    used = set()
    for i, value in enumerate(header):
        base = value.strip() or "column_" + str(i + 1)
        name = base
        suffix = 2
        while name in used:
            name = base + "_" + str(suffix)
            suffix += 1
        used.add(name)
        columns.append(name)

    rows = [row + [""] * (width - len(row)) for row in rows]
    return {"columns": columns, "rows": rows}
